import React,{useEffect,useState,useRef}from'react';import{Routes,Route,Navigate,useLocation,useNavigate}from'react-router-dom';import{LayoutDashboard,CheckSquare,Inbox,CalendarDays,FolderKanban,Users,ChartNoAxesCombined,Settings,Plus,Search,Bell,Sun,Moon,ChevronDown,PanelLeftClose,PanelLeft,LogOut,Command,ArrowRight,MoreHorizontal,Clock3,AlertCircle,Check,Filter,X,Target,Timer,Download,Trash2,MoveRight,Menu,CalendarCheck,Layers,MessageSquare,ArrowUpRight,MailCheck,RefreshCw}from'lucide-react';import{Toaster,toast}from'sonner';import{DndContext,PointerSensor,useSensor,useSensors,useDraggable,useDroppable,closestCorners}from'@dnd-kit/core';import{CSS}from'@dnd-kit/utilities';import{useAuth}from'./store';import api from'./api';
const nav=[['Overview',LayoutDashboard,'/app'],['My Tasks',CheckSquare,'/app/tasks'],['Focus Mode',Timer,'/app/focus'],['Inbox',Inbox,'/app/inbox'],['Calendar',CalendarDays,'/app/calendar'],['Projects',FolderKanban,'/app/projects'],['Team',Users,'/app/team'],['Reports',ChartNoAxesCombined,'/app/reports']];
function Brand({small=false}){return <div className="brand-mark"><span className="brand-icon"><Check size={17} strokeWidth={3}/></span>{!small&&<span>TASKAURA</span>}</div>}
function App(){
 const{token,user,setUser,logout}=useAuth(),location=useLocation();
 const[dark,setDark]=useState(localStorage.getItem('taskora-theme')==='dark');
 const[refresh,setRefresh]=useState(0),[createInitial,setCreateInitial]=useState(false),[showCreate,setShowCreate]=useState(false);
 const navigate=useNavigate(),inviteToken=new URLSearchParams(location.search).get('invite'),invitePath=inviteToken?`/app/team?invite=${encodeURIComponent(inviteToken)}`:'/app';
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('taskora-theme',dark?'dark':'light')},[dark]);
 useEffect(()=>{if(token)api.get('/auth/me').then(r=>setUser(r.data.user)).catch(()=>{})},[token,setUser]);
 const bump=()=>setRefresh(v=>v+1),openCreate=(initial=false)=>{setCreateInitial(initial);setShowCreate(true)};
 return <><Toaster position="top-right" richColors/><Routes>
  <Route path="/" element={token?<Navigate to="/app"/>:<Landing/>}/>
  <Route path="/login" element={token?<Navigate to={invitePath}/>:<AuthPage mode="login"/>}/>
  <Route path="/register" element={token?<Navigate to={invitePath}/>:<AuthPage mode="register"/>}/>
  <Route path="/app/*" element={token?<WorkspaceShell user={user} setUser={setUser} logout={logout} dark={dark} setDark={setDark} refresh={refresh} bump={bump} openCreate={openCreate}/>:<Navigate to={inviteToken?`/login?invite=${encodeURIComponent(inviteToken)}`:'/login'}/>}/>
 </Routes>{showCreate&&<CreateModal initial={createInitial} onClose={()=>setShowCreate(false)} onSaved={()=>{setShowCreate(false);bump()}}/>}</>;
}
function WorkspaceShell({user,setUser,logout,dark,setDark,refresh,bump,openCreate}){
 const location=useLocation(),navigate=useNavigate(),[collapsed,setCollapsed]=useState(false),[mobileMenu,setMobileMenu]=useState(false),[query,setQuery]=useState(''),[workspaceOpen,setWorkspaceOpen]=useState(false),[searchResults,setSearchResults]=useState(null),[searchOpen,setSearchOpen]=useState(false),[searchLoading,setSearchLoading]=useState(false);
 const current=nav.find(item=>item[2]===location.pathname)?.[0]||'Overview';
 const{data:notificationData}=useData('/notifications',refresh,60000),unreadCount=notificationData?.filter(item=>!item.read).length||0;
 const{data:workspaces}=useData('/workspaces',refresh),activeWorkspace=workspaces?.find(ws=>String(ws.id)===String(user?.workspace));
 async function switchWorkspace(id){try{const r=await api.patch(`/workspaces/${id}/active`);useAuth.getState().setSession(r.data.user,r.data.token);setWorkspaceOpen(false);bump();navigate('/app')}catch(e){toast.error(e.response?.data?.message||'Could not switch workspace')}}
 useEffect(()=>{const create=e=>openCreate(e.detail||false),reload=()=>bump();window.addEventListener('taskora-create',create);window.addEventListener('taskora-refresh',reload);return()=>{window.removeEventListener('taskora-create',create);window.removeEventListener('taskora-refresh',reload)}},[]);
 useEffect(()=>{const term=query.trim();if(term.length<2){setSearchResults(null);setSearchLoading(false);return}let active=true;setSearchLoading(true);const timer=window.setTimeout(()=>api.get('/search',{params:{q:term}}).then(r=>{if(active)setSearchResults(r.data)}).catch(()=>{if(active)setSearchResults(null)}).finally(()=>{if(active)setSearchLoading(false)}),250);return()=>{active=false;window.clearTimeout(timer)}},[query]);
 return <div className={`shell ${collapsed?'is-collapsed':''} ${mobileMenu?'mobile-open':''}`}>
  <aside className="sidebar">
   <div className="side-top"><Brand/><button className="icon-button collapse-btn" onClick={()=>setCollapsed(v=>!v)}>{collapsed?<PanelLeft size={18}/>:<PanelLeftClose size={18}/>}</button></div>
   <div className="workspace-switcher"><button className="workspace-switch" aria-expanded={workspaceOpen} onClick={()=>setWorkspaceOpen(v=>!v)}><span className="workspace-avatar">{(activeWorkspace?.name||user?.name||'T')[0]}</span><span className="workspace-copy"><b>{activeWorkspace?.name||`${user?.name?.split(' ')[0]||'My'} workspace`}</b><small>{activeWorkspace?.role||'Workspace'}</small></span><ChevronDown size={15}/></button>{workspaceOpen&&<div className="workspace-menu" role="menu">{workspaces?.map(ws=><button role="menuitem" className={ws.active?'active':''} key={ws.id} onClick={()=>switchWorkspace(ws.id)}><b>{ws.name}</b><small>{ws.role}</small></button>)}<button role="menuitem" onClick={()=>{setWorkspaceOpen(false);navigate('/app/team')}}><Plus size={14}/> Manage team</button></div>}</div>
   <button className="quick-create" onClick={()=>openCreate()}><Plus size={16}/><span>New task</span><kbd>N</kbd></button>
   <div className="nav-label">WORKSPACE</div><nav>{nav.map(([label,Icon,path])=><button key={path} className={`nav-link ${location.pathname===path?'active':''}`} title={collapsed?label:undefined} onClick={()=>{navigate(path);setMobileMenu(false)}}><Icon size={17}/><span>{label}</span></button>)}</nav>
   <div className="side-bottom"><button className="nav-link" onClick={()=>setDark(v=>!v)}><span className="nav-inline-icon">{dark?<Sun size={17}/>:<Moon size={17}/>}</span><span>{dark?'Light appearance':'Dark appearance'}</span></button><button className="nav-link" onClick={()=>navigate('/app/settings')}><Settings size={17}/><span>Settings</span></button><div className="profile-row"><span className="avatar">{user?.name?.[0]||'T'}</span><span className="profile-copy"><b>{user?.name||'Your account'}</b><small>{user?.email||'Welcome'}</small></span><button title="Sign out" className="icon-button" onClick={()=>{logout();navigate('/')}}><LogOut size={16}/></button></div></div>
  </aside>
   <main className="main-area"><header className="topbar"><div className="top-left"><button className="icon-button mobile-toggle" onClick={()=>setMobileMenu(v=>!v)}><Menu size={19}/></button><span className="breadcrumb-muted">Workspace</span><span className="crumb-slash">/</span><b>{current}</b></div><div className="top-actions"><div className="search-wrap"><label className="searchbox"><Search size={16}/><input placeholder="Search tasks, projects, people..." value={query} onFocus={()=>setSearchOpen(true)} onChange={e=>{setQuery(e.target.value);setSearchOpen(true)}}/><kbd>Ctrl K</kbd></label>{searchOpen&&query.trim().length>=2&&<SearchResults query={query} data={searchResults} loading={searchLoading} onClose={()=>setSearchOpen(false)} onSelect={(type,item)=>{setSearchOpen(false);if(type==='task'||type==='comment'){setQuery(type==='comment'?item.taskTitle:item.title);navigate('/app/tasks')}else if(type==='project')navigate('/app/projects');else if(type==='member')navigate('/app/team')}}/>}</div><button title={unreadCount?`${unreadCount} unread notifications`:'Notifications'} aria-label={unreadCount?`${unreadCount} unread notifications`:'Notifications'} className="icon-button notification-button" onClick={()=>navigate('/app/inbox')}><Bell size={17}/>{unreadCount>0&&<span className="notification-count">{unreadCount>9?'9+':unreadCount}</span>}</button><span className="top-avatar">{user?.name?.[0]||'T'}</span></div></header>
   <div className="content"><Routes><Route index element={<Dashboard user={user} onCreate={()=>openCreate()} refresh={refresh}/>}/><Route path="tasks" element={<Tasks onCreate={()=>openCreate()} refresh={refresh} query={query}/>}/><Route path="focus" element={<FocusMode/>}/><Route path="inbox" element={<InboxPage refresh={refresh}/>}/><Route path="calendar" element={<CalendarPage refresh={refresh} onCreate={date=>openCreate(date?{dueDate:date}:false)}/>}/><Route path="projects" element={<Projects refresh={refresh} onCreate={()=>openCreate('project')}/>}/><Route path="team" element={<Team user={user} refresh={refresh}/>}/><Route path="reports" element={<Reports refresh={refresh}/>}/><Route path="settings" element={<SettingsPage user={user} setUser={setUser} setDark={setDark}/>}/><Route path="*" element={<Dashboard user={user} onCreate={()=>openCreate()} refresh={refresh}/>}/></Routes></div>
  </main>
 </div>;
}function Landing(){return <div className="landing"><header className="landing-nav"><Brand/><div className="landing-links"><a href="#features">Features</a><a href="#workflow">How it works</a></div><div className="landing-right"><a className="text-link" href="/login">Log in</a><a className="btn primary" href="/register">Get started <ArrowRight size={15}/></a></div></header><section className="hero"><div className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot"/> A quieter way to get things done</div><h1>Bring clarity to<br/>everything you do<span className="period">.</span></h1><p>Organize tasks, manage projects, and make meaningful progress every day. One thoughtful workspace for all the work that matters.</p><div className="hero-buttons"><a href="/register" className="btn primary btn-large">Start planning <ArrowRight size={16}/></a><a href="#features" className="btn secondary btn-large">Explore features</a></div><div className="hero-proof"><div className="proof-avatars"><i>L</i><i>M</i><i>A</i></div><span>Made for focused work, together.</span></div></div><div className="hero-visual"><div className="preview-window"><div className="preview-top"><div className="window-dots"><i/><i/><i/></div><span>My workspace</span><MoreHorizontal size={18}/></div><div className="preview-body"><div className="preview-side"><div className="preview-brand"><span>ÃƒÂ¢Ã…â€œÃ¢â‚¬Å“</span> TASKAURA</div><div className="preview-nav active"><LayoutDashboard size={13}/> Overview</div><div className="preview-nav"><CheckSquare size={13}/> My Tasks</div><div className="preview-nav"><CalendarDays size={13}/> Calendar</div><div className="preview-nav"><FolderKanban size={13}/> Projects</div><div className="preview-mini-label">YOUR PROJECTS</div><div className="preview-project"><i/> Website refresh</div><div className="preview-project"><i/> Spring launch</div></div><div className="preview-main"><div className="preview-welcome">Good morning, Alex <span>ÃƒÂ¢Ã…â€œÃ‚Â³</span></div><div className="preview-date">MONDAY, MAY 20</div><div className="preview-stats"><div><small>Tasks completed</small><strong>12 <em>ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â€ 18%</em></strong><div className="mini-bars"><i/><i/><i/><i/><i/><i/><i/></div></div><div><small>Focus time</small><strong>4.5 <small>hrs</small></strong><div className="focus-line"/></div></div><div className="preview-section-head">Today <span>View all ÃƒÂ¢Ã¢â‚¬Â Ã¢â‚¬â„¢</span></div><div className="preview-task"><i className="unchecked"/><span>Finalize homepage wireframes</span><b>10:30</b></div><div className="preview-task"><i className="checked">ÃƒÂ¢Ã…â€œÃ¢â‚¬Å“</i><span className="faded">Review Q2 launch plan</span><b>Done</b></div><div className="preview-task"><i className="unchecked"/><span>Share progress with team</span><b>14:00</b></div><div className="preview-project-card"><div className="project-card-top"><span>Website refresh</span><span>68%</span></div><div className="progress-track"><i style={{width:'68%'}}/></div></div></div></div></div><div className="float-note"><span className="float-check"><Check size={13}/></span><span><b>One step at a time.</b><small>3 tasks wrapped up today</small></span></div></div><div className="hero-glow"/></section><section className="trust-strip"><span>LESS CHAOS. MORE MOMENTUM.</span><div><span>Individuals</span><i/><span>Small teams</span><i/><span>Big ideas</span></div></section><section id="features" className="feature-section"><div className="section-intro"><div className="eyebrow">A PLACE FOR YOUR WORK</div><h2>Everything in its<br/>right place.</h2><p>Less time searching for what's next. More time making it happen.</p></div><div className="feature-grid"><Feature icon={CheckSquare} title="Tasks that make sense" text="Shape your day with clear priorities, due dates, and a simple view of what deserves your attention."/><Feature icon={Layers} title="Projects with purpose" text="Keep the moving pieces together and see how small steps add up to meaningful progress."/><Feature icon={Users} title="Better, together" text="Share context, assign work, and keep your team in sync without adding another meeting."/></div></section><section id="workflow" className="workflow-section"><div className="workflow-copy"><div className="eyebrow">THE TASKAURA WAY</div><h2>From scattered<br/>to centered.</h2><p>Give your thoughts a home, your plans a shape, and your work a pace that feels right.</p><a className="inline-link" href="/register">Make room for focus <ArrowRight size={15}/></a></div><div className="workflow-steps"><div><span>01</span><strong>Capture what matters</strong><p>Put every idea and responsibility somewhere you can trust.</p></div><div><span>02</span><strong>Shape a clear plan</strong><p>Connect tasks to projects and choose the next right step.</p></div><div><span>03</span><strong>Make steady progress</strong><p>See your momentum grow as your work moves forward.</p></div></div></section><section className="closing-cta"><div className="closing-icon"><Target size={23}/></div><h2>Make space for your best work.</h2><p>Start with a clear view. Build momentum that lasts.</p><a href="/register" className="btn primary btn-large">Get started with Taskaura <ArrowRight size={16}/></a></section><footer className="landing-footer"><Brand/><span>Plan with purpose. Execute with clarity.</span><small>Copyright {new Date().getFullYear()} Taskaura</small></footer></div>}
function SearchResults({query,data,loading,onClose,onSelect}){const sections=[['Tasks','task',data?.tasks||[]],['Projects','project',data?.projects||[]],['People','member',data?.members||[]],['Comments','comment',data?.comments||[]]],count=sections.reduce((n,[,,items])=>n+items.length,0);return <div className="search-results" role="listbox" aria-label="Search results">{loading&&!data?<div className="search-empty">Searching your workspace...</div>:count===0?<div className="search-empty">No matches for “{query.trim()}”</div>:sections.map(([label,type,items])=>items.length>0&&<section className="search-group" key={type}><small>{label}</small>{items.map((item,i)=>{const title=type==='task'?item.title:type==='project'?item.name:type==='member'?item.name:item.taskTitle,detail=type==='task'?`${item.status} · ${item.priority}`:type==='project'?item.status:type==='member'?item.email:item.body;return <button role="option" key={item._id||item.taskId||i} onMouseDown={e=>e.preventDefault()} onClick={()=>{onSelect(type,item);onClose()}}><span className="search-result-title">{title}</span><span className="search-result-detail">{detail}</span></button>})}</section>)}</div>}
function Feature({icon:Icon,title,text}){return <article className="feature-card"><span className="feature-icon"><Icon size={19}/></span><h3>{title}</h3><p>{text}</p></article>}
function AuthPage({mode}){
 const login=mode==='login',navigate=useNavigate(),location=useLocation(),{setSession}=useAuth(),inviteToken=new URLSearchParams(location.search).get('invite'),invitePath=inviteToken?`/app/team?invite=${encodeURIComponent(inviteToken)}`:'/app';
 const[busy,setBusy]=useState(false),[resending,setResending]=useState(false),[verificationStep,setVerificationStep]=useState(false),[email,setEmail]=useState(''),[recoveryStep,setRecoveryStep]=useState(0),[recoveryEmail,setRecoveryEmail]=useState('');
 async function submit(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));setBusy(true);try{
  if(login&&recoveryStep===1){await api.post('/auth/forgot-password',{email:data.email});setRecoveryEmail(data.email);setRecoveryStep(2);toast.success('If an account exists for that email, a reset code has been sent.');return;}
  if(login&&recoveryStep===2){if(data.password!==data.confirmPassword){toast.error('Passwords do not match');return;}const r=await api.post('/auth/reset-password',{email:recoveryEmail,code:data.code,password:data.password});setRecoveryStep(0);toast.success(r.data.message||'Password reset. Sign in with your new password.');return;}
  if(login){const r=await api.post('/auth/login',{email:data.email,password:data.password});setSession(r.data.user,r.data.token);toast.success('Welcome back');navigate(invitePath);return;}
  if(!verificationStep){if(data.password!==data.confirmPassword){toast.error('Passwords do not match');return;}const r=await api.post('/auth/register',{name:data.name,email:data.email,password:data.password});setEmail(data.email);setVerificationStep(true);toast.success(r.data.message||'Check your email for a verification code');return;}
  const r=await api.post('/auth/verify-email',{email,code:data.code});setSession(r.data.user,r.data.token);toast.success('Email verified. Your workspace is ready.');navigate(invitePath);
 }catch(e){toast.error(e.response?.data?.message||'Could not connect to Taskaura')}finally{setBusy(false)}}
 async function resend(){setResending(true);try{const r=login&&recoveryStep===2?await api.post('/auth/forgot-password',{email:recoveryEmail}):await api.post('/auth/resend-otp',{email});toast.success(r.data.message||'A new code was sent')}catch(e){toast.error(e.response?.data?.message||'Could not resend the code')}finally{setResending(false)}}
 const requestRecovery=login&&recoveryStep===1,finishRecovery=login&&recoveryStep===2;
 return <div className="auth-page"><a className="auth-brand" href="/"><Brand/></a><div className="auth-card"><div className="eyebrow">{requestRecovery?'ACCOUNT RECOVERY':finishRecovery?'RESET PASSWORD':login?'WELCOME BACK':verificationStep?'EMAIL VERIFICATION':'A CLEARER WAY TO WORK'}</div><h1>{requestRecovery?'Reset your password.':finishRecovery?'Choose a new password.':login?'Good to see you.':verificationStep?'Check your inbox.':'Create your workspace.'}</h1><p>{requestRecovery?'Enter your account email. If it is registered, we will send a reset code.':finishRecovery?`Enter the six-digit code sent to ${recoveryEmail} and choose a new password.`:login?'Sign in to pick up where you left off.':verificationStep?`We sent a six-digit code to ${email}. Enter it below to finish signing up.`:'Start making progress on what matters.'}</p><form onSubmit={submit} className="auth-form">
 {!login&&verificationStep&&<><label>Email address<input type="email" value={email} readOnly/></label><label>Verification code<input name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" minLength="6" maxLength="6" placeholder="000000" onChange={e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,6)} required/></label></>}
 {!login&&!verificationStep&&<label>Full name<input name="name" placeholder="Your name" autoComplete="name" minLength="2" required/></label>}
 {requestRecovery&&<label>Email address<input name="email" type="email" placeholder="you@example.com" autoComplete="email" required/></label>}
 {finishRecovery&&<><label>Verification code<input name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" minLength="6" maxLength="6" placeholder="000000" onChange={e=>e.target.value=e.target.value.replace(/\D/g,'').slice(0,6)} required/></label><label>New password<input name="password" type="password" autoComplete="new-password" minLength="8" maxLength="100" required/></label><label>Confirm new password<input name="confirmPassword" type="password" autoComplete="new-password" minLength="8" maxLength="100" required/></label></>}
 {!verificationStep&&!requestRecovery&&!finishRecovery&&<><label>Email address<input name="email" type="email" placeholder="you@example.com" autoComplete="email" required/></label><label>Password<input name="password" type="password" placeholder={login?'Your password':'At least 8 characters'} autoComplete={login?'current-password':'new-password'} minLength="8" maxLength="100" required/></label>{!login&&<label>Confirm password<input name="confirmPassword" type="password" placeholder="Repeat your password" autoComplete="new-password" minLength="8" maxLength="100" required/></label>}</>}
 {login&&!recoveryStep&&<div className="forgot-line"><span>Use at least 8 characters.</span><button type="button" className="text-button" onClick={()=>setRecoveryStep(1)}>Forgot password?</button></div>}
 <button className="btn primary auth-submit" disabled={busy}>{busy?'Please wait...':requestRecovery?'Send reset code':finishRecovery?'Reset password':login?'Sign in':verificationStep?'Verify email':'Continue to email verification'} {verificationStep?<MailCheck size={15}/>:<ArrowRight size={15}/>}</button>
 </form>
 {!login&&verificationStep&&<div className="otp-actions"><button type="button" className="text-button" onClick={resend} disabled={resending}><RefreshCw size={13}/>{resending?'Sending...':'Resend code'}</button><button type="button" className="text-button" onClick={()=>setVerificationStep(false)}>Use a different email</button></div>}
 {finishRecovery&&<div className="otp-actions"><button type="button" className="text-button" onClick={resend} disabled={resending}><RefreshCw size={13}/>{resending?'Sending...':'Resend code'}</button></div>}
 <div className="auth-switch">{recoveryStep?<button type="button" className="text-button" onClick={()=>setRecoveryStep(0)}>Back to sign in</button>:<>{login?'New to Taskaura?':'Already have an account?'} <a href={login?`/register${inviteToken?`?invite=${encodeURIComponent(inviteToken)}`:''}`:`/login${inviteToken?`?invite=${encodeURIComponent(inviteToken)}`:''}`}>{login?'Create an account':'Sign in'}</a></>}</div></div><div className="auth-foot">Plan with purpose. Execute with clarity.</div></div>
}function useData(path,refresh=0,poll=0){const[data,setData]=useState(null),[error,setError]=useState('');useEffect(()=>{let alive=true;const load=()=>api.get(path).then(r=>alive&&setData(r.data)).catch(e=>alive&&setError(e.response?.data?.message||'Could not load data'));load();const timer=poll?window.setInterval(load,poll):null;return()=>{alive=false;if(timer)window.clearInterval(timer)}},[path,refresh,poll]);return{data,error,setData}}
function PageTitle({eyebrow,title,description,action,children}){return <div className="page-title-row"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1>{description&&<p>{description}</p>}</div><div className="title-actions">{children}{action}</div></div>}
function Dashboard({user,onCreate,refresh}){const{data}=useData('/dashboard',refresh);const{sdata}=useData('/activity',refresh);const d=data||{stats:{},today:[],upcoming:[],projects:[],byStatus:[],week:[]},stat=d.stats;const greet=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';return <><PageTitle eyebrow={new Date().toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'}).toUpperCase()} title={`${greet}, ${user?.name?.split(' ')[0]||'there'}.`} description="A little progress adds up. Here's what your day looks like." action={<button className="btn primary" onClick={onCreate}><Plus size={16}/> New task</button>}/><div className="stat-grid"><Stat label="Open tasks" value={stat.pending??'ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â'} icon={CheckSquare} detail="Ready when you are"/><Stat label="In progress" value={stat.inProgress??'ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â'} icon={Timer} detail="Moving forward"/><Stat label="Completed" value={stat.completed??'ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â'} icon={Check} detail={`${stat.completion??0}% overall completion`}/><Stat label="Overdue" value={stat.overdue??'ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â'} icon={AlertCircle} detail="Needs a quick look" danger={stat.overdue>0}/></div><div className="dashboard-grid"><section className="panel today-panel"><div className="panel-heading"><div><h2>Today's focus</h2><p>Keep your attention on the next step.</p></div><a href="/app/tasks">See all <ArrowRight size={14}/></a></div>{d.today?.length?d.today.slice(0,6).map(t=><TaskRow key={t._id} task={t} compact/>):<Empty icon={CalendarCheck} title="Your day has room to breathe" text="Tasks due today will appear here."/>}</section><section className="panel progress-panel"><div className="panel-heading"><div><h2>Weekly rhythm</h2><p>Tasks completed this week.</p></div><span className="chart-period">LAST 7 DAYS</span></div><div className="chart-wrap"><Chart data={d.week}/></div><div className="chart-footer"><span><i className="legend-dot"/> Completed</span><b>{stat.completed||0} <small>tasks overall</small></b></div></section><section className="panel projects-panel"><div className="panel-heading"><div><h2>Active projects</h2><p>Keep the big picture in view.</p></div><a href="/app/projects">All projects <ArrowRight size={14}/></a></div>{d.projects?.length?d.projects.map(p=><a className="project-row" href="/app/projects" key={p._id}><span className="project-dot" style={{background:p.color}}/><span className="project-row-name"><b>{p.name}</b><small>{p.targetDate?`Due ${new Date(p.targetDate).toLocaleDateString('en',{month:'short',day:'numeric'})}`:'No deadline'}</small></span><span className="project-progress"><i><em style={{width:`${p.progress||0}%`}}/></i><small>{p.progress||0}%</small></span></a>):<Empty icon={FolderKanban} title="Start with a project" text="Give a bigger goal a place to grow."/>}</section><section className="panel upcoming-panel"><div className="panel-heading"><div><h2>Coming up</h2><p>Deadlines on the horizon.</p></div><Clock3 size={17}/></div>{d.upcoming?.length?d.upcoming.map(t=><div className="upcoming-row" key={t._id}><span className={`priority-dot ${t.priority?.toLowerCase()}`}/><span>{t.title}</span><time>{t.dueDate?new Date(t.dueDate).toLocaleDateString('en',{month:'short',day:'numeric'}):'ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â'}</time></div>):<Empty icon={Clock3} title="Nothing coming up" text="Add a due date to see what's next."/>}</section></div></>}
function Stat({label,value,icon:Icon,detail,danger}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><Icon size={17}/></div><strong className={danger?'danger-text':''}>{value}</strong><small>{detail}</small></div>}
function Chart({data=[]}){return <div className="bar-chart">{data.map((x,i)=><div className="bar-item" key={x.name}><div className="bar-column"><i style={{height:`${Math.max(8,Math.min(100,x.completed*27))}%`}} title={`${x.completed} completed`}/></div><small>{x.name}</small></div>)}</div>}
function Empty({icon:Icon,title,text}){return <div className="empty-state"><Icon size={19}/><b>{title}</b><span>{text}</span></div>}
function TaskRow({task:t,compact=false,onChange}){return <div className="task-row"><button aria-label={t.status==='Completed'?'Reopen task':'Complete task'} className={`task-check ${t.status==='Completed'?'checked':''}`} onClick={()=>{const status=t.status==='Completed'?'To Do':'Completed';api.patch(`/tasks/${t._id}`,{status}).then(r=>{toast.success(status==='Completed'?'Task completed':'Task reopened');onChange?.(r.data);window.dispatchEvent(new Event('taskora-refresh'))}).catch(()=>toast.error('Could not update task'))}}>{t.status==='Completed'&&<Check size={12}/>}</button><div className="task-row-body"><span className={t.status==='Completed'?'task-done':''}>{t.title}</span>{!compact&&<small>{t.project?.name||'Personal'}{t.dueDate?` Ãƒâ€šÃ‚Â· Due ${new Date(t.dueDate).toLocaleDateString('en',{month:'short',day:'numeric'})}`:''}</small>}</div><span className={`priority-label ${t.priority?.toLowerCase()}`}>{t.priority}</span></div>}
function Tasks({onCreate,refresh,query}){const[showArchived,setShowArchived]=useState(false),{data}=useData(showArchived?'/tasks?archived=true':'/tasks',refresh),[tasks,setTasks]=useState([]),[view,setView]=useState('board'),[filter,setFilter]=useState('All tasks'),[selected,setSelected]=useState(null);useEffect(()=>{if(data?.items)setTasks(data.items)},[data]);const filtered=tasks.filter(t=>(filter==='All tasks'||t.status===filter)&&(!query||t.title.toLowerCase().includes(query.toLowerCase())));async function moveTask(id,status){try{const {data}=await api.patch(`/tasks/${id}`,{status});setTasks(t=>t.map(a=>a._id===id?data:a));toast.success('Task moved')}catch{toast.error('Could not move task')}}const sensors=useSensors(useSensor(PointerSensor,{activationConstraint:{distance:8}}));return <><PageTitle eyebrow={showArchived?'PAST WORK':'YOUR WORK, IN VIEW'} title={showArchived?'Archived tasks':'My tasks'} description={showArchived?'Keep completed or paused work organized.':'Make the next step visible and the rest will follow.'} action={<button className="btn primary" onClick={onCreate}><Plus size={16}/> Add task</button>}/><div className="toolbar"><div className="segmented"><button className={view==='board'?'selected':''} onClick={()=>setView('board')}><Layers size={14}/> Board</button><button className={view==='list'?'selected':''} onClick={()=>setView('list')}><CheckSquare size={14}/> List</button></div><label className="select-wrap"><Filter size={14}/><select value={filter} onChange={e=>setFilter(e.target.value)}>{['All tasks','Backlog','To Do','In Progress','In Review','Completed','Cancelled'].map(x=><option key={x}>{x}</option>)}</select><ChevronDown size={13}/></label><button className="btn secondary" onClick={()=>{setShowArchived(v=>!v);setFilter('All tasks')}}>{showArchived?'Active tasks':'Archived'}</button><span className="result-count">{filtered.length} {filtered.length===1?'task':'tasks'}</span></div>{view==='board'?<DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={({active,over})=>{if(!over)return;const status=String(over.id).startsWith('column:')?String(over.id).slice(7):tasks.find(t=>t._id===over.id)?.status;if(status&&tasks.find(t=>t._id===active.id)?.status!==status)moveTask(active.id,status)}}><div className="kanban">{['Backlog','To Do','In Progress','In Review','Completed','Cancelled'].map(status=><KanbanColumn key={status} status={status} tasks={filtered.filter(t=>t.status===status)} count={filtered.filter(t=>t.status===status).length} onSelect={setSelected} onStatus={moveTask}/>)}</div></DndContext>:<div className="panel task-list">{filtered.length?filtered.map(t=><div className="task-list-entry" key={t._id} onClick={()=>setSelected(t)}><TaskRow task={t}/><button className="icon-button" onClick={e=>{e.stopPropagation();setSelected(t)}}><MoreHorizontal size={17}/></button></div>):<Empty icon={CheckSquare} title="No tasks in this view" text="A fresh start is a good place to begin."/>}</div>}{selected&&<TaskDetail task={selected} archivedPage={showArchived} onClose={()=>setSelected(null)} onSaved={t=>{setTasks(x=>x.map(z=>z._id===t._id?t:z));setSelected(t)}} onDeleted={id=>{setTasks(x=>x.filter(z=>z._id!==id));setSelected(null)}} onArchived={id=>{setTasks(x=>x.filter(z=>z._id!==id));setSelected(null)}} onRestored={t=>{setTasks(x=>x.filter(z=>z._id!==t._id));setSelected(null)}} onDuplicated={t=>setTasks(x=>[t,...x])}/>}</>}
function KanbanColumn({status,tasks,count,onSelect,onStatus}){const {setNodeRef}=useDroppable({id:`column:${status}`});return <div ref={setNodeRef} className="kanban-column"><div className="kanban-head"><span className={`column-dot dot-${status.toLowerCase().replaceAll(' ','-')}`}/><b>{status}</b><small>{count}</small><button className="icon-button" title="Add task" onClick={()=>window.dispatchEvent(new CustomEvent('taskora-create',{detail:{status}}))}><Plus size={15}/></button></div><div className="kanban-stack">{tasks.map(t=><DraggableTask key={t._id} task={t} onClick={()=>onSelect(t)}/>)}</div></div>}
function DraggableTask({task:t,onClick}){const {attributes,listeners,setNodeRef,transform,isDragging}=useDraggable({id:t._id});return <div ref={setNodeRef} style={{transform:CSS.Transform.toString(transform),opacity:isDragging ? .55 : 1}} {...attributes} {...listeners} className="kanban-card" onClick={onClick}><div className="kanban-card-top"><span className={`priority-label ${t.priority?.toLowerCase()}`}>{t.priority}</span><button className="icon-button"><MoreHorizontal size={15}/></button></div><b>{t.title}</b>{t.description&&<p>{t.description}</p>}<div className="kanban-card-foot"><span>{t.project?.name||'Personal'}</span><span>{t.dueDate?new Date(t.dueDate).toLocaleDateString('en',{month:'short',day:'numeric'}):<span className="muted">No date</span>}</span></div><div className="kanban-card-actions"><select aria-label="Change task status" value={t.status} onClick={e=>e.stopPropagation()} onChange={e=>api.patch(`/tasks/${t._id}`,{status:e.target.value}).then(()=>window.dispatchEvent(new Event('taskora-refresh')))}>{['Backlog','To Do','In Progress','In Review','Completed','Cancelled'].map(s=><option key={s}>{s}</option>)}</select>{t.assignee?.name&&<span className="assignee-mini" title={t.assignee.name}>{t.assignee.name[0]}</span>}</div></div>}
function TaskDetail({task,onClose,onSaved,onDeleted,onArchived,onRestored,onDuplicated,archivedPage}){const[t,setT]=useState(task),[busy,setBusy]=useState(false);useEffect(()=>setT(task),[task]);async function save(patch){try{const r=await api.patch(`/tasks/${task._id}`,patch);setT(r.data);onSaved(r.data)}catch(e){toast.error(e.response?.data?.message||'Could not save changes')}}async function duplicate(){setBusy(true);try{const r=await api.post(`/tasks/${task._id}/duplicate`);onDuplicated(r.data);toast.success('Task duplicated');onClose()}catch(e){toast.error(e.response?.data?.message||'Could not duplicate task')}finally{setBusy(false)}}async function archive(){setBusy(true);try{await api.patch(`/tasks/${task._id}/archive`);toast.success('Task archived');onArchived(task._id)}catch(e){toast.error(e.response?.data?.message||'Could not archive task')}finally{setBusy(false)}}async function restore(){setBusy(true);try{const r=await api.patch(`/tasks/${task._id}/restore`);toast.success('Task restored');onRestored(r.data)}catch(e){toast.error(e.response?.data?.message||'Could not restore task')}finally{setBusy(false)}}return <div className="drawer-backdrop" onClick={onClose}><aside className="task-drawer" onClick={e=>e.stopPropagation()}><div className="drawer-head"><span className="eyebrow">TASK DETAILS</span><button className="icon-button" onClick={onClose}><X size={18}/></button></div><input className="detail-title" value={t.title} onChange={e=>setT({...t,title:e.target.value})} onBlur={()=>t.title!==task.title&&save({title:t.title})}/><label className="detail-label">Description<textarea value={t.description||''} placeholder="Add context, notes, or links..." onChange={e=>setT({...t,description:e.target.value})} onBlur={()=>save({description:t.description})}/></label><div className="detail-fields"><label>Status<select value={t.status} onChange={e=>{setT({...t,status:e.target.value});save({status:e.target.value})}}>{['Backlog','To Do','In Progress','In Review','Completed','Cancelled'].map(s=><option key={s}>{s}</option>)}</select></label><label>Priority<select value={t.priority} onChange={e=>{setT({...t,priority:e.target.value});save({priority:e.target.value})}}>{['Low','Medium','High','Urgent'].map(s=><option key={s}>{s}</option>)}</select></label></div><div className="detail-fields"><label>Start date<input type="date" value={t.startDate?t.startDate.slice(0,10):''} onChange={e=>{const startDate=e.target.value||null;setT({...t,startDate});save({startDate})}}/></label><label>Due date<input type="date" value={t.dueDate?t.dueDate.slice(0,10):''} onChange={e=>{const dueDate=e.target.value||null;setT({...t,dueDate});save({dueDate})}}/></label></div><label className="detail-label">Estimated duration · minutes<input type="number" min="0" value={t.estimatedMinutes||0} onChange={e=>setT({...t,estimatedMinutes:Number(e.target.value)})} onBlur={()=>save({estimatedMinutes:Number(t.estimatedMinutes)||0})}/></label><label className="detail-label">Tags<input value={(t.tags||[]).join(', ')} placeholder="Planning, research" onChange={e=>setT({...t,tags:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})} onBlur={()=>save({tags:t.tags||[]})}/></label><div className="detail-subtasks"><div className="subtask-head"><b>Subtasks</b><button onClick={()=>{const subtasks=[...(t.subtasks||[]),{title:'New subtask',completed:false}];setT({...t,subtasks});save({subtasks})}}><Plus size={14}/> Add</button></div>{t.subtasks?.map((s,i)=><label key={s._id||i} className="subtask-row"><input type="checkbox" checked={s.completed} onChange={e=>{const subtasks=t.subtasks.map((x,j)=>j===i?{...x,completed:e.target.checked}:x);setT({...t,subtasks});save({subtasks})}}/><input value={s.title} onChange={e=>setT({...t,subtasks:t.subtasks.map((x,j)=>j===i?{...x,title:e.target.value}:x)})} onBlur={()=>save({subtasks:t.subtasks})}/></label>)}</div>{!archivedPage&&<TimeTracker id={t._id} entries={t.timeEntries||[]} onSaved={r=>{setT(r);onSaved(r)}}/>}<div className="comment-section"><b>Comments</b>{t.comments?.map((c,i)=><div className="comment-item" key={c._id||i}><span className="avatar small">{c.name?.[0]}</span><div><strong>{c.name}</strong><p>{c.body}</p></div></div>)}{!archivedPage&&<CommentForm id={t._id} onSaved={c=>{const next={...t,comments:[...(t.comments||[]),c]};setT(next);onSaved(next)}}/>}</div><div className="task-detail-actions"><button className="btn secondary" onClick={duplicate} disabled={busy}><Layers size={14}/> Duplicate</button>{archivedPage?<button className="btn primary" onClick={restore} disabled={busy}><RefreshCw size={14}/> Restore task</button>:<button className="btn secondary" onClick={archive} disabled={busy}><Download size={14}/> Archive</button>}</div><button className="delete-task" onClick={async()=>{if(!confirm(`Delete “${t.title}”? This cannot be undone.`))return;try{await api.delete(`/tasks/${t._id}`);toast.success('Task deleted');onDeleted(t._id)}catch{toast.error('Could not delete task')}}}><Trash2 size={15}/> Delete task</button></aside></div>}function TimeTracker({id,entries=[],onSaved}){const key=`taskaura-focus-${id}`,read=()=>{try{return JSON.parse(localStorage.getItem(key)||'{}')}catch{return{}}},initial=read(),[elapsed,setElapsed]=useState(Number(initial.elapsedSeconds)||0),[startedAt,setStartedAt]=useState(Number(initial.startedAt)||null),[now,setNow]=useState(Date.now()),[saving,setSaving]=useState(false);useEffect(()=>{const saved=read();setElapsed(Number(saved.elapsedSeconds)||0);setStartedAt(Number(saved.startedAt)||null);setNow(Date.now())},[id]);useEffect(()=>{if(elapsed||startedAt)localStorage.setItem(key,JSON.stringify({elapsedSeconds:elapsed,startedAt}));else localStorage.removeItem(key)},[key,elapsed,startedAt]);useEffect(()=>{if(!startedAt)return;const timer=window.setInterval(()=>setNow(Date.now()),1000);return()=>window.clearInterval(timer)},[startedAt]);const seconds=elapsed+(startedAt?Math.max(0,Math.floor((now-startedAt)/1000)):0),display=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;function toggle(){if(startedAt){setElapsed(seconds);setStartedAt(null);}else{setNow(Date.now());setStartedAt(Date.now());}}async function finish(){if(seconds<1)return;const minutes=Math.max(1,Math.round(seconds/60));setElapsed(seconds);setStartedAt(null);setSaving(true);try{const r=await api.post(`/tasks/${id}/time`,{minutes});onSaved?.(r.data);setElapsed(0);setStartedAt(null);setNow(Date.now());toast.success(`${minutes} minute${minutes===1?'':'s'} logged`)}catch{toast.error('Could not save tracked time. Your timer is paused; try again.')}finally{setSaving(false)}}return <section className="time-tracker"><div><span className="eyebrow">FOCUS SESSION</span><strong>{display}</strong><small>{startedAt?'Stay with this one thing.':'Make a little room for focused work.'}</small></div><div className="time-controls">{startedAt?<button className="btn secondary" onClick={toggle}>Pause</button>:<button className="btn primary" onClick={toggle}>{seconds?'Resume':'Start focus'}</button>}{seconds>0&&<button className="btn secondary" onClick={finish} disabled={saving}>{saving?'Saving...':'Finish & save'}</button>}</div>{entries.length>0&&<div className="time-history"><b>Recent sessions</b>{entries.slice(-5).reverse().map((entry,i)=><small key={entry._id||i}>{entry.minutes} min · {new Date(entry.loggedAt).toLocaleString('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small>)}</div>}</section>}function CommentForm({id,onSaved}){const[body,setBody]=useState('');return <form className="comment-form" onSubmit={async e=>{e.preventDefault();if(!body.trim())return;try{const r=await api.post(`/tasks/${id}/comments`,{body});onSaved(r.data);setBody('')}catch{toast.error('Could not add comment')}}}><input value={body} onChange={e=>setBody(e.target.value)} placeholder="Write a comment..."/><button aria-label="Send comment"><ArrowRight size={15}/></button></form>}
function CreateModal({initial,onClose,onSaved}){const isProject=initial==='project',defaults=typeof initial==='object'?initial:{},[mode,setMode]=useState(isProject?'project':'task'),[projects,setProjects]=useState([]),[busy,setBusy]=useState(false);useEffect(()=>{api.get('/projects').then(r=>setProjects(r.data)).catch(()=>{})},[]);const project=mode==='project';async function submit(e){e.preventDefault();setBusy(true);const d=Object.fromEntries(new FormData(e.currentTarget));try{await api.post(project?'/projects':'/tasks',project?{name:d.title,description:d.description,color:d.color||'#526b57',targetDate:d.dueDate||null,status:'Active'}:{title:d.title,description:d.description,status:d.status||defaults.status||'To Do',priority:d.priority||'Medium',startDate:d.startDate||null,dueDate:d.dueDate||null,project:d.project||null,estimatedMinutes:Number(d.estimatedMinutes)||0});toast.success(project?'Project created':'Task created');onSaved()}catch(e){toast.error(e.response?.data?.message||'Could not create item')}finally{setBusy(false)}}return <div className="modal-backdrop" onClick={onClose}><div className="create-modal" onClick={e=>e.stopPropagation()}><div className="modal-head"><div><span className="eyebrow">A NEW BEGINNING</span><h2>{project?'Create a project':'Add a task'}</h2></div><button className="icon-button" onClick={onClose}><X size={18}/></button></div><div className="create-tabs"><button className={!project?'active':''} onClick={()=>setMode('task')}><CheckSquare size={15}/> Task</button><button className={project?'active':''} onClick={()=>setMode('project')}><FolderKanban size={15}/> Project</button></div><form onSubmit={submit}><label>{project?'Project name':'Task title'}<input name="title" placeholder={project?'e.g. Website refresh':'What needs to get done?'} autoFocus required maxLength="180"/></label><label>Description <span className="optional">OPTIONAL</span><textarea name="description" placeholder="Add a little context..." rows="3"/></label>{!project&&<div className="form-two"><label>Priority<select name="priority" defaultValue="Medium">{['Low','Medium','High','Urgent'].map(s=><option key={s}>{s}</option>)}</select></label><label>Start date<input type="date" name="startDate" defaultValue={defaults.startDate||""}/></label><label>Due date<input type="date" name="dueDate" defaultValue={defaults.dueDate||""}/></label></div>}{project&&<div className="form-two"><label>Target date<input type="date" name="dueDate" defaultValue={defaults.dueDate||""}/></label><label>Color<select name="color"><option value="#526b57">Sage</option><option value="#c28b55">Amber</option><option value="#6c8291">Slate</option><option value="#96788e">Mauve</option></select></label></div>}{!project&&<><label>Project<select name="project" defaultValue={defaults.project||""}><option value="">Personal task</option>{projects.map(p=><option key={p._id} value={p._id}>{p.name}</option>)}</select></label><label>Estimated time <span className="optional">MINUTES</span><input name="estimatedMinutes" type="number" min="0" placeholder="e.g. 45"/></label></>}<div className="modal-actions"><button type="button" className="btn secondary" onClick={onClose}>Cancel</button><button className="btn primary" disabled={busy}>{busy?'Saving...':project?'Create project':'Create task'} <ArrowRight size={14}/></button></div></form></div></div>}
function Projects({refresh,onCreate}){const{data,setData}=useData('/projects',refresh);const projects=data||[],[selected,setSelected]=useState(null);return <><PageTitle eyebrow="THE BIG PICTURE" title="Projects" description="Connect the small steps to something bigger." action={<button className="btn primary" onClick={onCreate}><Plus size={15}/> New project</button>}/>{projects.length?<div className="projects-grid">{projects.map(p=><article className="project-card" key={p._id} onClick={()=>setSelected(p)}><div className="project-card-heading"><span className="project-color" style={{background:p.color}}/><span className="status-pill">{p.status}</span><button className="icon-button" onClick={e=>{e.stopPropagation();setSelected(p)}}><MoreHorizontal size={17}/></button></div><h2>{p.name}</h2><p>{p.description||'A shared place to keep this work moving.'}</p><div className="project-card-meta"><span><Layers size={14}/>{p.taskCount||0} tasks</span><span><CalendarDays size={14}/>{p.targetDate?new Date(p.targetDate).toLocaleDateString('en',{month:'short',day:'numeric',year:'numeric'}):'No deadline'}</span></div><div className="project-card-progress"><div><span>Progress</span><b>{p.progress||0}%</b></div><i><em style={{width:`${p.progress||0}%`,background:p.color}}/></i></div><div className="project-card-bottom"><span className="avatar small">{p.owner?.name?.[0]||'Y'}</span><span>Updated {new Date(p.updatedAt).toLocaleDateString('en',{month:'short',day:'numeric'})}</span><ArrowUpRight size={15}/></div></article>)}</div>:<div className="panel empty-panel"><Empty icon={FolderKanban} title="Give your next big idea a home" text="Projects help you connect tasks, deadlines, and progress in one calm place."/><button className="btn primary" onClick={onCreate}><Plus size={15}/> Create a project</button></div>}{selected&&<ProjectDetail project={selected} refresh={refresh} onClose={()=>setSelected(null)} onDeleted={()=>{setSelected(null);setData(projects.filter(p=>p._id!==selected._id))}} onUpdated={updated=>{if(updated.status==='Archived'){setData(projects.filter(p=>p._id!==updated._id));setSelected(null)}else{setData(projects.map(p=>p._id===updated._id?updated:p));setSelected(updated)}}}/>}</>}
