 const[form,setForm]=useState({name:user?.name||'',theme:user?.theme||'light'}),[password,setPassword]=useState({currentPassword:'',password:'',confirmPassword:''}),[savingPassword,setSavingPassword]=useState(false),[deletePassword,setDeletePassword]=useState('');
